<?php
require __DIR__.'/../config/auth.php';requireLogin();require __DIR__.'/../config/db.php';require __DIR__.'/../config/layout.php';
$title=$title??'Activo';$subtitle=$subtitle??'';$image=$image??'logo-naser.png';$sectorSlugs=$sectorSlugs??[];
$visible=sectoresVisibles($pdo);$visibleMap=array_column($visible,'id','slug');$allowedIds=[];foreach($sectorSlugs as $slug){if(isset($visibleMap[$slug]))$allowedIds[]=(int)$visibleMap[$slug];}
$docs=[];if($allowedIds){$ph=implode(',',array_fill(0,count($allowedIds),'?'));$st=$pdo->prepare("SELECT d.*,s.nombre sector FROM documentos d JOIN sectores s ON s.id=d.sector_id WHERE d.activo=1 AND d.sector_id IN ($ph) ORDER BY d.fecha_actualizacion DESC LIMIT 12");$st->execute($allowedIds);$docs=$st->fetchAll();}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($title)?> | NASER</title><link rel="stylesheet" href="<?=app_url('/style.css')?>"></head><body><div class="app"><?php sidebar($pdo,'inicio');?><main class="content"><header class="section-top"><div><p class="eyebrow">GESTIÓN DE RECURSOS</p><h1><?=h($title)?></h1><p><?=h($subtitle)?></p></div><a class="btn secondary" href="<?=app_url('/php/dashboard.php')?>">Volver al panel</a></header><section class="asset-hero"><img src="<?=app_url('/img/'.$image)?>" alt="<?=h($title)?>"><div><p class="eyebrow">FICHA OPERATIVA</p><h2><?=h($title)?></h2><p>Acceso rápido a documentación, procedimientos, controles e información relacionada con este recurso.</p><div class="asset-links"><a class="btn primary" href="<?=app_url('/php/buscar.php?q='.urlencode($title))?>">Buscar documentación</a><a class="btn secondary" href="<?=app_url('/php/operaciones.php')?>">Ver operaciones</a></div></div></section><div class="section-head"><div><p class="eyebrow">DOCUMENTACIÓN RELACIONADA</p><h2>Últimos documentos de sectores asociados</h2></div></div><section class="document-grid"><?php if(!$docs):?><div class="empty">Todavía no hay documentación cargada en los sectores relacionados.</div><?php endif;?><?php foreach($docs as $d):?><article class="document-card"><span class="type-badge"><?=h($d['sector'])?></span><h3><?=h($d['titulo'])?></h3><p><?=h($d['descripcion']?:'Documento relacionado.')?></p><?php if($d['archivo']):?><div class="doc-actions"><a class="btn primary" target="_blank" href="<?=app_url('/uploads/'.rawurlencode($d['archivo']))?>">Abrir</a></div><?php endif;?></article><?php endforeach;?></section></main></div></body></html>
